import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Integer.parseInt(st.nextToken());
        long b = Integer.parseInt(st.nextToken());
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        long ans;
        if (a == 1) {
            long r = b % 6;
            if (r <= 3) ans = b - r;
            else if (r == 4) ans = b - 2;
            else ans = b - 1;
        } else if (a <= 5 && b <= 30) {
            ans = solveSmall((int) a, (int) b);
        } else {
            ans = a * b - a * b % 2;
        }
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.println(ans);
        out.close();
    }

    static int solveSmall(int n, int m) {
        int states = 1 << (3 * n);
        int[][][] dp = new int[m + 1][n + 1][states];
        for (int col = 0; col <= n; col++) {
            for (int mask = 0; mask < states; mask++) {
                dp[m][col][mask] = mask == 0 ? 0 : Integer.MIN_VALUE;
            }
        }
        for (int row = m - 1; row >= 0; row--) {
            for (int mask = 0; mask < states; mask++) {
                dp[row][n][mask] = dp[row + 1][0][mask];
            }
            for (int col = n - 1; col >= 0; col--) {
                for (int mask = 0; mask < states; mask++) {
                    if ((mask & 1) == 1) {
                        dp[row][col][mask] = dp[row][col + 1][mask >> 1];
                        continue;
                    }
                    int val = dp[row][col + 1][mask >> 1];
                    val = Math.max(val, dp[row][col + 1][(mask >> 1) + (1 << (3 * n - 1))] + 2);
                    if (col != 0 && ((mask >> (2 * n - 1)) & 1) == 0) {
                        val = Math.max(val, dp[row][col + 1][(mask >> 1) + (1 << (2 * n - 2))] + 2);
                    }
                    if (col != n - 1 && ((mask >> (2 * n + 1)) & 1) == 0) {
                        val = Math.max(val, dp[row][col + 1][(mask >> 1) + (1 << (2 * n))] + 2);
                    }
                    if (col >= 2 && ((mask >> (n - 2)) & 1) == 0) {
                        val = Math.max(val, dp[row][col + 1][(mask >> 1) + (1 << (n - 3))] + 2);
                    }
                    if (col < n - 1 && ((mask >> (n + 2)) & 1) == 0) {
                        val = Math.max(val, dp[row][col + 1][(mask >> 1) + (1 << (n + 1))] + 2);
                    }
                    dp[row][col][mask] = val;
                }
            }
        }
        return dp[0][0][0];
    }
}
